"""Fail closed on disclosed evaluation rows or repeated sentence contexts in training."""
import unicodedata


def context_key(row):
    values = [row.get(name) for name in ('prefix', 'typed', 'expectedSpelling')]
    if any(not isinstance(value, str) for value in values):
        raise ValueError('CONTEXT_ROW_SCHEMA')
    return tuple(' '.join(unicodedata.normalize('NFC', value).casefold().split()) for value in values)


def target_context_key(row):
    prefix, _, target = context_key(row)
    return prefix, target


def check_separation(partitions, disclosed):
    """Sentence identity and left-context/target identity must not cross boundaries."""
    disclosed = tuple(disclosed)
    forbidden_rows = {context_key(row) for row in disclosed}
    forbidden_contexts = {target_context_key(row) for row in disclosed}
    forbidden_sentences = {row['article'] for row in disclosed if row.get('article')}
    seen_contexts, seen_sentences = {}, {}
    for part, rows in partitions.items():
        for row in rows:
            key = context_key(row)
            context = target_context_key(row)
            sentence = row.get('article')
            if (key in forbidden_rows or context in forbidden_contexts or sentence in forbidden_sentences
                    or row.get('purpose') == 'REGRESSION_ONLY_NOT_TRAINING'):
                raise ValueError('DISCLOSED_EVALUATION_REUSED')
            if context in seen_contexts and seen_contexts[context] != part:
                raise ValueError('CONTEXT_SPLIT_OVERLAP')
            if sentence and sentence in seen_sentences and seen_sentences[sentence] != part:
                raise ValueError('SENTENCE_SPLIT_OVERLAP')
            seen_contexts[context] = part
            if sentence:
                seen_sentences[sentence] = part

holdout_ledger.py:
"""Durable public-data exclusions, independent of ignored corpus directories.

Hashes identify public records; they do not anonymize private text. The bootstrap
ledger is deliberately incomplete. Known overlaps are rejected immediately;
absence of overlap cannot certify freshness until historical coverage is complete.
No old generator or qualification requirement is changed by this module.
"""
import argparse
import base64
import binascii
import copy
import hashlib
import json
from pathlib import Path
import re
import unicodedata

from conversation_split_checks import target_context_key
from source_identities import ewt_document_identity, tatoeba_identity

SCHEMA = 1
KEY_SCHEMA = 'rune-public-exclusions-v1'
KINDS = ('article', 'family', 'sentence', 'context')
USAGES = ('supervised', 'disclosed', 'reserved', 'historical-exclusion', 'historical-family-exclusion', 'historical-source-exclusion', 'prepared-training-quarantine', 'historical-context-exclusion')
_HASH = re.compile(r'[0-9a-f]{64}\Z')
PACKED_ENCODING = 'sha256-raw-base64-v1'
MAX_PACKED_KEYS = 2_000_000


def _unpack_keys(value):
    if (not isinstance(value,dict) or set(value)!={'encoding','count','sha256','data'} or
            value['encoding']!=PACKED_ENCODING or type(value['count']) is not int or
            not 1<=value['count']<=MAX_PACKED_KEYS or not isinstance(value['data'],str) or
            not isinstance(value['sha256'],str) or not _HASH.fullmatch(value['sha256']) or
            len(value['data'])!=4*((value['count']*32+2)//3)):
        raise ValueError('LEDGER_PACKED_KEYS')
    try:raw=base64.b64decode(value['data'],validate=True)
    except (ValueError,binascii.Error):raise ValueError('LEDGER_PACKED_KEYS') from None
    if (len(raw)!=value['count']*32 or base64.b64encode(raw).decode('ascii')!=value['data'] or
            hashlib.sha256(raw).hexdigest()!=value['sha256']):
        raise ValueError('LEDGER_PACKED_KEYS')
    return [raw[offset:offset+32].hex() for offset in range(0,len(raw),32)]


def pack_ledger(ledger,minimum=1000):
    """Return compact storage with exactly the same validated logical entries."""
    if type(minimum) is not int or minimum<1:raise ValueError('LEDGER_PACK_THRESHOLD')
    result=validate_ledger(copy.deepcopy(ledger))
    for entry in result['entries']:
        for axis,values in entry['keys'].items():
            if minimum<=len(values)<=MAX_PACKED_KEYS:
                raw=b''.join(bytes.fromhex(value) for value in values)
                entry['keys'][axis]=dict(encoding=PACKED_ENCODING,count=len(values),
                    sha256=hashlib.sha256(raw).hexdigest(),data=base64.b64encode(raw).decode('ascii'))
    return result


def _text(value):
    if not isinstance(value, str) or not value.strip():
        raise ValueError('LEDGER_KEY_SCHEMA')
    return ' '.join(unicodedata.normalize('NFC', value).casefold().split())


def _digest(kind, value):
    encoded = json.dumps([KEY_SCHEMA, kind, value], ensure_ascii=False, separators=(',', ':')).encode()
    return hashlib.sha256(encoded).hexdigest()


def require_source_segment(row):
    """New Wikipedia proposals must identify their source selector segment."""
    if not isinstance(row, dict): raise ValueError('LEDGER_ROW_SCHEMA')
    if row.get('sourceRepository') in (None, 'wikimedia/wikipedia'):
        segment = row.get('sourceSegmentHash')
        if not isinstance(segment, str) or not _HASH.fullmatch(segment):
            raise ValueError('LEDGER_SOURCE_SEGMENT_SCHEMA')


def source_segment_hash(text):
    """Hash a source-verified whole selector segment using the shared normalization."""
    if not isinstance(text, str) or not text.strip(): raise ValueError('LEDGER_SOURCE_SEGMENT_TEXT')
    normalized = ' '.join(unicodedata.normalize('NFC', text).casefold().split())
    return hashlib.sha256(normalized.encode('utf-8')).hexdigest()


def keys_for(rows, kind):
    if kind not in KINDS:
        raise ValueError('LEDGER_KEY_KIND')
    result = set()
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError('LEDGER_ROW_SCHEMA')
        if kind == 'article':
            sentence=ewt_document_identity(row) if row.get('sourceRepository') == 'ud-english-ewt' else tatoeba_identity(row)
            if sentence is not None:
                result.add(_digest(kind,sentence));continue
            article = row.get('article')
            if (not isinstance(article, str) or not 1 <= len(article) <= 20
                    or not article.isascii() or not article.isdecimal()):
                raise ValueError('LEDGER_ARTICLE_SCHEMA')
            result.add(_digest(kind, ['wikipedia', str(int(article))]))
        elif kind == 'family':
            families = row.get('families', [row.get('family')])
            if not isinstance(families, (list, tuple)) or not families:
                raise ValueError('LEDGER_FAMILY_SCHEMA')
            for family in families:
                normalized = _text(family)
                # Native morphology IDs are not Pymorph lemmas and must not
                # silently occupy the same key namespace.
                if normalized.isdecimal():
                    raise ValueError('LEDGER_FAMILY_SCHEMA')
                result.add(_digest(kind, ['pymorph-lemma-ru', normalized]))
        elif kind == 'sentence':
            sentence=ewt_document_identity(row) if row.get('sourceRepository') == 'ud-english-ewt' else tatoeba_identity(row)
            value = row.get('sentenceHash') if sentence is not None else row.get('contextHash')
            if not isinstance(value, str) or not _HASH.fullmatch(value):
                raise ValueError('LEDGER_SENTENCE_SCHEMA')
            result.add(_digest(kind, ['tatoeba-full-sentence-normalized-v1' if sentence is not None else 'right-context-source-hash-v1', value]))
            # Wikipedia proposals can carry both the historical target window and
            # a separately source-verified complete selector-segment hash.
            if sentence is None and 'sourceSegmentHash' in row:
                segment = row['sourceSegmentHash']
                if not isinstance(segment, str) or not _HASH.fullmatch(segment):
                    raise ValueError('LEDGER_SOURCE_SEGMENT_SCHEMA')
                result.add(_digest(kind, ['tatoeba-full-sentence-normalized-v1', segment]))
        else:
            # Same typo-independent normalization as the existing split guard.
            prefix, target = target_context_key(row)
            result.add(_digest(kind, [prefix, target]))
    return result


def validate_ledger(ledger):
    if (not isinstance(ledger, dict) or type(ledger.get('schema')) is not int or ledger.get('schema') != SCHEMA
            or ledger.get('keySchema') != KEY_SCHEMA or ledger.get('publicDataOnly') is not True):
        raise ValueError('LEDGER_SCHEMA')
    coverage = ledger.get('coverage')
    if (not isinstance(coverage, dict) or type(coverage.get('complete')) is not bool
            or not isinstance(coverage.get('pending'), list)
            or any(not isinstance(p, str) or not p for p in coverage['pending'])
            or (coverage['complete'] and coverage['pending'])):
        raise ValueError('LEDGER_COVERAGE')
    entries = ledger.get('entries')
    if not isinstance(entries, list) or not entries:
        raise ValueError('LEDGER_ENTRIES')
    ids = set()
    for entry in entries:
        if (not isinstance(entry, dict) or not isinstance(entry.get('id'), str) or not entry['id']
                or entry['id'] in ids or entry.get('usage') not in USAGES
                or not isinstance(entry.get('bindings'), dict) or not entry['bindings']
                or any(not isinstance(p, str) or not p or not isinstance(h, str)
                       or not _HASH.fullmatch(h) for p, h in entry['bindings'].items())):
            raise ValueError('LEDGER_ENTRY')
        ids.add(entry['id'])
        generators = entry.get('generatorBindings')
        if generators is not None and (not isinstance(generators, dict) or not generators
                or any(not isinstance(p, str) or not p or not isinstance(h, str)
                       or not _HASH.fullmatch(h) for p, h in generators.items())):
            raise ValueError('LEDGER_GENERATOR_BINDING')
        keys = entry.get('keys'); missing = entry.get('missingAxes')
        if (not isinstance(keys, dict) or not keys or not set(keys) <= set(KINDS)
                or not isinstance(missing, list) or any(k not in KINDS for k in missing)
                or set(keys) & set(missing) or (coverage['complete'] and missing)):
            raise ValueError('LEDGER_ENTRY_KEYS')
        if entry['usage'] in ('supervised', 'historical-family-exclusion', 'prepared-training-quarantine'):
            if set(keys) != {'family'} or missing:
                raise ValueError('LEDGER_SUPERVISED_FAMILY_SCOPE')
        elif entry['usage']=='historical-source-exclusion':
            if set(keys)!={'article','sentence'} or missing:raise ValueError('LEDGER_SOURCE_SCOPE')
        elif entry['usage']=='historical-context-exclusion':
            if set(keys)!={'context'} or missing:raise ValueError('LEDGER_CONTEXT_SCOPE')
        elif set(keys) | set(missing) != set(KINDS):
            raise ValueError('LEDGER_ENTRY_AXES_UNDECLARED')
        for axis,values in keys.items():
            if isinstance(values,dict):
                values=_unpack_keys(values)
                keys[axis]=values
            if (not isinstance(values, list) or not values or
                    any(not isinstance(v, str) or not _HASH.fullmatch(v) for v in values)
                    or values != sorted(set(values))):
                raise ValueError('LEDGER_ENTRY_KEYS')
        if 'unsupportedSurfaceKeys' in entry:
            values=entry['unsupportedSurfaceKeys']
            if (not isinstance(values,list) or not values or any(not isinstance(v,str) or not _HASH.fullmatch(v) for v in values)
                    or values!=sorted(set(values))):raise ValueError('LEDGER_UNSUPPORTED_SURFACES')
    return ledger


def load_ledger(path):
    return validate_ledger(json.loads(Path(path).read_text()))


def assert_disjoint(rows, ledger, *, kinds, usages=None, require_complete=True):
    validate_ledger(ledger)
    if (not isinstance(kinds, (tuple, list)) or not kinds or not set(kinds) <= set(KINDS)
            or (usages is not None and (not isinstance(usages, (tuple, list))
                or not usages or not set(usages) <= set(USAGES)))
            or type(require_complete) is not bool):
        raise ValueError('LEDGER_CHECK_PROFILE')
    rows = tuple(rows)
    if not rows:
        raise ValueError('LEDGER_EMPTY_ROWS')
    for kind in kinds:
        proposed = keys_for(rows, kind)
        blocked = {v for e in ledger['entries'] if usages is None or e['usage'] in usages
                   for v in e['keys'].get(kind, [])}
        if proposed & blocked:
            raise ValueError('LEDGER_OVERLAP:' + kind)
    if require_complete and not ledger['coverage']['complete']:
        raise ValueError('LEDGER_INCOMPLETE')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--ledger', type=Path, default=Path(__file__).with_name('holdout-ledger.json'))
    parser.add_argument('--validate-only', action='store_true')
    parser.add_argument('--rows', type=Path)
    parser.add_argument('--profile', choices=('new-sentences', 'new-families'), default='new-sentences')
    args = parser.parse_args()
    ledger = load_ledger(args.ledger)
    if args.validate_only:
        if args.rows:
            parser.error('--validate-only does not check rows')
        print(json.dumps(dict(schemaValid=True, freshnessCoverageComplete=ledger['coverage']['complete'],
                              entries=len(ledger['entries']))))
        return
    if args.rows is None:
        parser.error('--rows is required for a freshness check')
    rows = [json.loads(line) for line in args.rows.read_text().splitlines() if line.strip()]
    for row in rows:
        require_source_segment(row)
    # Existing new-sentence protocol allows previously evaluated families, but
    # never supervised families. Legacy family-novel protocols exclude all.
    assert_disjoint(rows, ledger, kinds=('family',),
                    usages=('supervised','prepared-training-quarantine') if args.profile == 'new-sentences' else None,
                    require_complete=False)
    assert_disjoint(rows, ledger, kinds=('article', 'sentence', 'context'))
    print('LEDGER_DISJOINT')


if __name__ == '__main__':
    try:
        main()
    except ValueError as error:
        raise SystemExit(str(error)) from error

